    c0=min(j for i,j in xs); c1=max(j for i,j in xs)
    o=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and (i in (r0,r1) and c0<=j<=c1 or j in (c0,c1) and r0<=i<=r1):
                o[i][j]=fill
    return o
