import collections
def colors(gi,go):
    cnt=collections.Counter(v for row in gi for v in row)
    bg=cnt.most_common(1)[0][0]
    ocolors={v for row in go for v in row}
    icolors=set(cnt)
    fill=(ocolors-icolors) or {v for v in ocolors if cnt[v]<min(cnt.values())}
    fill=list(fill)[0] if fill else None
    mark=({v for v in icolors if v!=bg} - {fill})
    return bg, (list(mark)[0] if mark else None), fill
