def solve5(gi,bg,mark,fill=2):
    R,C=len(gi),len(gi[0]); out=[row[:] for row in gi]
    rs=[r for r in range(R) if any(gi[r][c]==mark for c in range(C))]
    cs=[c for c in range(C) if any(gi[r][c]==mark for r in range(R))]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    for r,c in {(r0,c0),(r0,c1),(r1,c0),(r1,c1)}:
        if out[r][c]==bg: out[r][c]=fill
    def comp_h(r,a,b):
        for c in range(a,b+1):
            if out[r][c]==bg: out[r][c]=fill
    def comp_v(c,a,b):
        for r in range(a,b+1):
            if out[r][c]==bg: out[r][c]=fill
    def mline_h(ln):
        m=[c for c in range(C) if gi[ln][c]==mark]
        if ln in (r0,r1):
            if gi[ln][c0]!=mark: m=[c0]+m
            if gi[ln][c1]!=mark: m=m+[c1]
        return sorted(set(m))
    def mline_v(ln):
        m=[r for r in range(R) if gi[r][ln]==mark]
        if ln in (c0,c1):
            if gi[r0][ln]!=mark: m=[r0]+m
            if gi[r1][ln]!=mark: m=m+[r1]
        return sorted(set(m))
    for ln in (r0,r1):
        m=mline_h(ln)
        if len(m)>=2: comp_h(ln,m[0],m[-1])
    for ln in (c0,c1):
        m=mline_v(ln)
        if len(m)>=2: comp_v(ln,m[0],m[-1])
    for r in range(R):
        if r in (r0,r1): continue
        m=[c for c in range(C) if gi[r][c]==mark]
        if len(m)>=4: comp_h(r,c0,c1)
    for c in range(C):
        if c in (c0,c1): continue
        m=[r for r in range(R) if gi[r][c]==mark]
        if len(m)>=4: comp_v(c,r0,r1)
    return out

