def crossed(gi,r,c,bg,R,C):
    # mark at (r,c) has non-bg on both perpendicular sides
    v = (r>0 and gi[r-1][c]!=bg) and (r<R-1 and gi[r+1][c]!=bg)
    h = (c>0 and gi[r][c-1]!=bg) and (c<C-1 and gi[r][c+1]!=bg)
    return v,h

def solve6(gi,bg,mark,fill=2,mode='both'):
    R,C=len(gi),len(gi[0]); out=[row[:] for row in gi]
    rs=[r for r in range(R) if any(gi[r][c]==mark for c in range(C))]
    cs=[c for c in range(C) if any(gi[r][c]==mark for r in range(R))]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    # virtual corners on border rows/cols
    vrow={r0:([c0] if gi[r0][c0]!=mark else [])+([c1] if gi[r0][c1]!=mark else []),
          r1:([c0] if gi[r1][c0]!=mark else [])+([c1] if gi[r1][c1]!=mark else [])}
    vcol={c0:([r0] if gi[r0][c0]!=mark else [])+([r1] if gi[r1][c0]!=mark else []),
          c1:([r0] if gi[r0][c1]!=mark else [])+([r1] if gi[r1][c1]!=mark else [])}
    def fillgaps(seq):  # seq of positions (sorted) -> fill gaps between consecutive
        for a,b in zip(seq,seq[1:]):
            for x in range(a+1,b):
                yield x
    # border rows: fill all gaps
    for ln in (r0,r1):
        m=sorted([c for c in range(C) if gi[ln][c]==mark]+vrow[ln])
        for x in fillgaps(m):
            if out[ln][x]==bg: out[ln][x]=fill
    for ln in (c0,c1):
        m=sorted([r for r in range(R) if gi[r][ln]==mark]+vcol[ln])
        for x in fillgaps(m):
            if out[x][ln]==bg: out[x][ln]=fill
    # interior lines: fill gap iff endpoints crossed (both perp sides non-bg)
    for r in range(R):
        if r in (r0,r1): continue
        m=[c for c in range(C) if gi[r][c]==mark]
        for a,b in zip(m,m[1:]):
            ok1,ok2=crossed(gi,r,a,bg,R,C)[1],crossed(gi,r,b,bg,R,C)[1]
            if ok1 and ok2:
                for x in range(a+1,b):
                    if out[r][x]==bg: out[r][x]=fill
    for c in range(C):
        if c in (c0,c1): continue
        m=[r for r in range(R) if gi[r][c]==mark]
        for a,b in zip(m,m[1:]):
            ok1,ok2=crossed(gi,a,c,bg,R,C)[0],crossed(gi,b,c,bg,R,C)[0]
            if ok1 and ok2:
                for x in range(a+1,b):
                    if out[x][c]==bg: out[x][c]=fill
    return out

